mapper.select:
SELECT *
FROM inventory_reservation
WHERE source_document_type = #{sourceDocumentType}
  AND source_document_item_id = #{sourceDocumentItemId}
  AND status = 'ACTIVE'
  AND deleted = FALSE

SELECT r.id, r.warehouse_id, r.sku_id, r.source_document_type, r.source_document_id, r.source_document_item_id, r.quantity, r.unit_snapshot, r.status, r.occurred_at, r.operator, r.created_at, w.warehouse_code, w.name AS warehouse_name, k.sku_code, k.spec_name AS sku_name, p.name AS product_name, s.order_no AS source_document_no FROM inventory_reservation r LEFT JOIN warehouse w ON w.id = r.warehouse_id LEFT JOIN product_sku k ON k.id = r.sku_id LEFT JOIN product_spu p ON p.id = k.spu_id LEFT JOIN sales_order s ON s.id = r.source_document_id WHERE r.deleted = FALSE
AND r.warehouse_id = #{query.warehouseId}
AND r.sku_id = #{query.skuId}
AND r.status = #{query.status}
AND r.source_document_id = #{query.sourceDocumentId}
ORDER BY r.created_at DESC, r.id DESC
